const countryCodes = [
  '971','966','973','974','965','968','962','963','964','967','970','961',
  '249','218','216','213','212','222','223','224','225','226','227','228',
  '20','30','31','32','33','34','36','39','40','41','43','44','45','46',
  '47','48','49','51','52','53','54','55','56','57','58','60','61','62',
  '63','64','65','66','81','82','84','86','90','91','92','93','94','95',
  '98','1','7'
];

// أطول Country Code الأول
const sortedCodes = [...countryCodes].sort((a, b) => b.length - a.length);

function getShift() {
  const cairoTime = new Date().toLocaleString('en-US', {
    timeZone: 'Africa/Cairo'
  });
  const hour = new Date(cairoTime).getHours();
  if (hour >= 8 && hour < 14) {
    return 'الصباح';
  }
  if (hour >= 14 && hour < 18) {
    return 'المساء';
  }
  if (hour >= 18 && hour < 22) {
    return 'الليل';
  }
  return 'الليل';
}

const items = $input.all();
const results = [];

for (const item of items) {
  const body = item.json?.body || {};

  // =========================
  // Sender Data
  // =========================
  const senderData = body.senderData || {};
  const chatId = senderData.chatId || '';
  const sender = senderData.sender || '';

  // هل الرسالة من Group؟
  const isGroup = chatId.endsWith('@g.us');
  item.json.isGroup = isGroup;

  // تجاهل رسائل الجروبات بالكامل
  if (isGroup) {
    continue;
  }

  // =========================
  // Get Customer Number
  // =========================
  /*
    Normal WhatsApp:
    chatId = <YOUR_WHATSAPP_ID>@c.us
  */
  const phoneId = chatId;

  if (!phoneId) {
    item.json.countryCode = '';
    item.json.phoneNumber = '';
  } else {
    const raw = phoneId
      .replace('@c.us', '')
      .replace('@g.us', '');

    const matched = sortedCodes.find(code =>
      raw.startsWith(code)
    );

    if (matched) {
      item.json.countryCode = matched;
      item.json.phoneNumber =
        raw.substring(matched.length);
    } else {
      item.json.countryCode = '';
      item.json.phoneNumber = raw;
    }
  }

  // =========================
  // Message Data
  // =========================
  const messageData = body.messageData || {};
  const extData =
    messageData.extendedTextMessageData || {};

  // =========================
  // Source
  // =========================
  item.json.source = 'whatsapp';

  // =========================
  // Ad Title
  // =========================
  item.json.adTitle =
    extData.title || '';

  // =========================
  // Shift
  // =========================
  item.json.shift = getShift();

  // =========================
  // Return
  // =========================
  results.push(item);
}

return results;

