const RPM_LIMIT = 30; // ← غيّرها لحد الـ RPM الفعلي بتاع خطتك
const minGapMs = 60000 / RPM_LIMIT;

const record = $('RateLimiter').item.json;
const lastCall = record?.fields?.timestamp || 0;
const now = Date.now();

const elapsed = now - lastCall;
const waitMs = Math.max(0, minGapMs - elapsed);

return [{
  json: {
    ...$('Merge').item.json,
    recordId: record.id, // مهم عشان نحدث نفس السجل بعدين
    waitSeconds: waitMs / 1000,
    reservedTime: now + waitMs
  }
}];

